const app=document.querySelector('#app');
const api=async(path,options={})=>{const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||'A apărut o eroare.');return data};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>s?new Date(s).toLocaleDateString('ro-RO',{day:'numeric',month:'long',year:'numeric'}):'—';
const weekdays=['Luni','Marți','Miercuri','Joi','Vineri','Sâmbătă','Duminică'];
let me=null, dash=null, publicShop=null, publicSelection={service:'',staff:'',date:'',time:''},toastTimer;
function toast(s){let old=document.querySelector('.toast');if(old)old.remove();let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3300)}
function brand(){return `<a class="brand" href="#"><span class="brand-mark">✂</span>tunspro</a>`}
function shellHeader(right=''){return `<header class="subnav"><div class="wrap nav">${brand()}<div class="navlinks"><a href="#cauta">Caută un frizer</a><a href="#cum-functioneaza">Cum funcționează</a></div><div class="navright">${right||'<a class="btn" href="#connect">Conectează-ți frizeria ↗</a>'}</div></div></header>`}
function home(){return `${shellHeader('<a class="login" href="#login">Intră în cont</a><a class="btn" href="#connect">Conectează-ți frizeria ↗</a>')}<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Programări fără telefoane</div><h1>Mai puțin timp<br>la telefon.<br><span>Mai mult timp</span><br>la scaun.</h1><p class="hero-copy">Găsește frizerii cu programări active, alege serviciul și rezervă online în câteva secunde.</p><div class="hero-actions"><a class="btn lime" href="#cauta">Caută un frizer <span>↗</span></a><a class="btn ghost" href="#connect">Ai o frizerie?</a></div><div class="socialproof"><span>Programări online, direct la frizeria aleasă</span></div></div><div class="hero-visual"><span class="visual-tag">✦ Programare confirmată în câteva secunde</span><div class="barber-art">💈</div><div class="booking-card"><div class="booking-top"><div><strong>Programare, simplu.</strong><br>Serviciu · frizer · oră</div><span>✂</span></div><div class="mini-slots"><span>09:30</span><span class="active">10:00</span><span>10:30</span><span>11:00</span></div></div></div></div></section><section class="section" id="cum-functioneaza"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Pentru clienți</div><h2>Găsești. Alegi.<br>Te-ai programat.</h2></div><p class="section-sub">Cauți un frizer după oraș, serviciu sau nume. Vezi locurile libere reale și rezervi fără să-ți faci cont.</p></div><div class="steps"><article class="step"><span class="step-icon">⌕</span><span class="step-num">01 / CAUTĂ</span><h3>Frizerul potrivit</h3><p>Descoperă doar frizeriile cu abonament activ și profil public actualizat.</p></article><article class="step"><span class="step-icon">◷</span><span class="step-num">02 / ALEGE</span><h3>Serviciu și oră</h3><p>Vezi durata, prețul și intervalele disponibile pentru frizerul preferat.</p></article><article class="step"><span class="step-icon">✓</span><span class="step-num">03 / REZERVĂ</span><h3>Confirmare rapidă</h3><p>Programarea apare imediat în dashboardul frizeriei.</p></article></div><div class="feature-inner" style="margin-top:50px"><div><div class="eyebrow">Pentru frizerii</div><h2>Agenda ta, în ordine.</h2><p>Administrează servicii, echipă și program. Abonamentul TunsPro costă 49 lei pe lună.</p><a class="btn" href="#connect">Creează contul frizeriei ↗</a></div></div></div></section><footer class="footer"><div class="wrap"><span>© 2026 TunsPro</span><span>Operator: Ion Andrei Ronaldo</span><a href="#confidentialitate">Confidențialitate</a><a href="mailto:tunsprogramari@gmail.com">Contact</a></div></footer>`}
function privacyPage(){return `${shellHeader('<a href="#">← Înapoi</a>')}<main class="wrap legal-page"><div class="eyebrow">Informații juridice</div><h1>Politica de confidențialitate</h1><p class="legal-updated">Ultima actualizare: 7 octombrie 2026</p><p>TunsPRO este un brand operat de <strong>Ion Andrei Ronaldo</strong>. Pentru întrebări despre datele personale, ne poți contacta la <a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a> sau la adresa Strada Ghiocei Nr. 11A, Urziceni, județul Ialomița.</p><h2>Ce date folosim și de ce</h2><p><strong>Clienți:</strong> numele, numărul de telefon și, dacă este furnizat, e-mailul; împreună cu frizeria, serviciul, frizerul, data și ora rezervării. Le folosim pentru a înregistra și administra programarea, pentru afișarea ei în agenda frizeriei și pentru notificările solicitate/activate.</p><p><strong>Frizerii:</strong> numele titularului, e-mailul de cont, parola stocată sub formă de hash, datele profilului frizeriei, fotografiile încărcate pentru profilul public, serviciile, echipa și programul. Fotografiile de profil devin vizibile public. Acestea sunt necesare pentru cont, administrarea profilului și abonament.</p><p><strong>Abonament:</strong> păstrăm identificatorii Stripe ai clientului și abonamentului, starea și perioada abonamentului. Datele cardului sunt gestionate de Stripe Checkout; TunsPRO nu le stochează.</p><p>Prelucrăm datele pentru furnizarea programărilor și a contului solicitat, administrarea abonamentului și securitatea serviciului. Frizeria aleasă vede în dashboard datele necesare pentru programare. Ea poate avea propriile obligații și informări privind datele pe care le primește.</p><h2>Cât timp păstrăm datele</h2><p>Numele și datele de contact ale clientului sunt anonimizate automat la 12 luni după încheierea programării. Rămân doar informațiile de programare fără identificatorii clientului. Datele contului frizeriei se păstrează cât timp contul este activ; pentru ștergere sau o solicitare de acces, rectificare ori ștergere, scrie-ne la adresa de contact de mai sus. Unele date pot fi păstrate în continuare când legea o cere sau pentru soluționarea unor litigii.</p><h2>Furnizori și transferuri</h2><p>Serviciul este găzduit de Render, cu infrastructura aplicației în Statele Unite. Render poate prelucra date în numele TunsPRO conform termenilor și garanțiilor sale de transfer. Stripe procesează abonamentele, iar furnizorii de e-mail/SMS (SMTP/Twilio) sunt folosiți numai dacă sunt configurați. Fonturile sunt încărcate de la Google Fonts, ceea ce poate transmite către Google date tehnice de conexiune, precum adresa IP și informații despre browser.</p><h2>Drepturile tale</h2><p>În condițiile legii, poți solicita accesul, rectificarea, ștergerea sau restricționarea prelucrării, te poți opune ori poți cere portabilitatea datelor. Poți depune o plângere la Autoritatea Națională de Supraveghere a Prelucrării Datelor cu Caracter Personal (<a href="https://www.dataprotection.ro/" target="_blank" rel="noopener">ANSPDCP</a>). Pentru exercitarea drepturilor, contactează-ne la <a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a>.</p><h2>Cookie-uri și securitate</h2><p>Folosim un cookie tehnic de sesiune, HttpOnly, pentru autentificarea dashboardului frizeriei. Nu folosim cookie-uri de analiză în interfața actuală. Aplicăm măsuri tehnice precum parole hash-uite, sesiuni protejate și acces la programări doar pentru contul frizeriei asociate.</p><p class="legal-note">Această pagină descrie funcționarea actuală a platformei. Dacă se schimbă furnizorii, funcțiile sau datele prelucrate, informațiile vor fi actualizate.</p></main><footer class="footer"><div class="wrap"><span>Operator: Ion Andrei Ronaldo · brand TunsPRO</span><a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a><a href="#">Înapoi la început</a></div></footer>`}
function authPage(kind){let isReg=kind==='connect';return `${shellHeader('<a href="#">← Înapoi</a>')}<main class="success-wrap"><form id="auth-form" class="success-card connect-card"><div class="eyebrow" style="justify-content:center">${isReg?'Configurează frizeria':'Bine ai revenit'}</div><h1>${isReg?'Creează contul frizeriei':'Intră în cont'}</h1><p>${isReg?'După înscriere, adaugi serviciile, echipa și programul. Profilul devine public după activarea abonamentului.':'Gestionează programările și profilul frizeriei.'}</p>${isReg?`<div class="connect-fields"><label class="field-label">Numele tău<input required class="input" name="owner" autocomplete="name"></label><label class="field-label">Numele frizeriei<input required class="input" name="name"></label><label class="field-label">E-mail<input required class="input" type="email" name="email" autocomplete="email"></label><label class="field-label">Parolă (minim 10 caractere)<input required class="input" type="password" minlength="10" name="password" autocomplete="new-password"></label><label class="field-label">Oraș<input required class="input" name="city"></label><label class="field-label">Adresă<input required class="input" name="address"></label><label class="field-label">Telefon frizerie<input required class="input" type="tel" name="phone"></label><label class="field-label">Descriere<input class="input" name="tagline"></label></div>`:`<label class="field-label" style="text-align:left">E-mail<input required class="input" type="email" name="email" autocomplete="email"></label><label class="field-label" style="text-align:left">Parolă<input required class="input" type="password" name="password" autocomplete="current-password"></label>`}<button class="btn full" style="margin-top:20px">${isReg?'Creează cont și continuă →':'Intră în dashboard →'}</button><p style="font-size:12px">${isReg?'Ai deja cont?':'Nu ai cont?'} <a href="#${isReg?'login':'connect'}"><strong>${isReg?'Intră în cont':'Creează contul frizeriei'}</strong></a></p></form></main>`}
async function searchPage(query=''){let d=await api('/api/public/shops?q='+encodeURIComponent(query));return `${shellHeader()}<main class="wrap directory-main"><div class="eyebrow">Găsește-ți următorul tuns</div><h1>Un frizer bun,<br><span>la un search distanță.</span></h1><p class="directory-lead">Caută după numele frizeriei, oraș, frizer sau serviciu.</p><div class="directory-search"><span>⌕</span><input id="shop-search" type="search" value="${esc(query)}" placeholder="ex. fade, Andrei, București" autocomplete="off"><kbd>/</kbd></div><div class="directory-results"><strong id="result-count">${d.shops.length} ${d.shops.length===1?'frizerie găsită':'frizerii găsite'}</strong><span>Abonament activ · Profiluri disponibile</span></div><div id="search-results" class="directory-grid">${d.shops.map(s=>`<article class="directory-card"><div class="directory-cover"><span>✂</span><span class="pill">PROGRAMĂRI ACTIVE</span></div><div class="directory-content"><div class="directory-person"><span class="barber-face">💈</span><div><h2>${esc(s.name)}</h2><small>${esc(s.tagline||'Frizerie')}</small></div></div><h3>${esc(s.city)}</h3><p>📍 ${esc(s.address)}</p><div class="directory-tags">${s.services.slice(0,3).map(x=>`<span>${esc(x.name)} · ${x.price} lei</span>`).join('')||'<span>Servicii în curs de configurare</span>'}</div><a class="btn full" href="#frizerie/${encodeURIComponent(s.slug)}">Vezi profilul și rezervă</a></div></article>`).join('')}</div><div class="empty-results ${d.shops.length?'hidden':''}"><span>⌕</span><h2>Nu am găsit frizerii disponibile.</h2><p>În acest moment sunt listate doar frizeriile cu abonament activ. Încearcă alt oraș sau revino mai târziu.</p><p>Ai o frizerie? <a href="#connect"><strong>Creează primul profil</strong></a></p></div></main>`}
async function profilePage(slug){let {shop}=await api('/api/public/shops/'+encodeURIComponent(slug));publicShop=shop;if(!publicSelection.service&&shop.services[0])publicSelection.service=String(shop.services[0].id);if(!publicSelection.staff&&shop.team[0])publicSelection.staff=String(shop.team[0].id);if(!publicSelection.date){let d=new Date();d.setDate(d.getDate()+1);publicSelection.date=d.toISOString().slice(0,10)}return `${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="wrap" style="padding-top:27px"><section class="salon-hero"><div class="salon-identity"><span class="pill">PROGRAMĂRI ONLINE ACTIVE</span><h1>${esc(shop.name)}</h1><div class="salon-meta"><span>📍 ${esc(shop.address)}, ${esc(shop.city)}</span><span>✦ ${esc(shop.tagline||'Frizerie')}</span></div></div></section>${galleryMarkup(shop)}<div class="salon-grid"><section class="salon-main"><h2>Servicii</h2><div class="service-list">${shop.services.map(s=>`<button class="service ${String(s.id)===publicSelection.service?'selected':''}" data-select-service="${s.id}"><span><strong>${esc(s.name)}</strong><small>${s.duration} min · ${esc(s.description||'')}</small></span><span class="service-price">${s.price} lei</span></button>`).join('')||'<p>Servicii indisponibile momentan.</p>'}<h2 style="margin-top:31px">Echipa</h2><div class="barbers">${shop.team.map(t=>`<button class="barber ${String(t.id)===publicSelection.staff?'selected':''}" data-select-staff="${t.id}"><span class="barber-face">✂</span><span><strong>${esc(t.name)}</strong><small>${esc(t.role)}</small></span></button>`).join('')}</div><div style="margin-top:32px"><h2>Alege data</h2><input class="input" id="booking-date" type="date" value="${esc(publicSelection.date)}" min="${new Date().toISOString().slice(0,10)}"></div></section><aside class="book-card"><h3>Ore disponibile</h3><p>${esc(shop.name)} · ${esc(shop.city)}</p><div id="available-slots" class="slots"><span class="manage-note">Alege serviciul, frizerul și data.</span></div><form id="booking-form"><label class="field-label">Numele tău<input required class="input" name="client" autocomplete="name"></label><label class="field-label">Telefon<input required class="input" name="phone" type="tel" autocomplete="tel"></label><label class="field-label">E-mail (opțional)<input class="input" name="email" type="email" autocomplete="email"></label><p class="privacy-inline">Datele sunt folosite pentru gestionarea programării. <a href="#confidentialitate" target="_blank">Politica de confidențialitate</a> · păstrare: 12 luni, apoi anonimizare.</p><button class="btn full" style="margin-top:15px" ${publicSelection.time?'':'disabled'}>Confirmă programarea</button></form><div id="booking-summary" class="booking-summary"><span>Selectează o oră</span></div></aside></div></main>`}
function dashboardShell(content,active){return `<div class="dashboard"><div class="dash-layout"><aside class="sidebar">${brand()}<div class="side-label">FRIZERIA MEA</div><nav>${[['dashboard','Programări','▦'],['dashboard-services','Servicii','✂'],['dashboard-team','Echipa','♙'],['dashboard-hours','Programul echipei','◷'],['dashboard-profile','Profil public','▣'],['dashboard-abonament','Abonament','▤'],['dashboard-notificari','Notificări','✉']].map(([route,label,ico])=>`<a class="side-link ${active===route?'active':''}" href="#${route}"><span class="ico">${ico}</span><span class="label">${label}</span></a>`).join('')}<a class="side-link" href="#logout"><span class="ico">↪</span><span class="label">Ieșire din cont</span></a></nav><div class="side-bottom"><strong>${esc(dash?.shop?.name||'Frizeria')}</strong><div style="color:var(--muted);margin-top:5px">${esc(dash?.shop?.city||'')}</div></div></aside><main class="dash-main">${content}</main></div></div>`}
function appointmentPage(){let rows=dash.bookings.map(b=>`<tr><td><strong>${new Date(b.starts).toLocaleString('ro-RO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</strong></td><td class="client-cell">${esc(b.client)}<small>${esc(b.phone)} ${b.email?`· ${esc(b.email)}`:''}</small></td><td>${esc(b.service_name)}<small>${b.price} lei · ${b.duration} min</small></td><td>${esc(b.staff_name)}</td><td><button class="filter-btn" data-cancel="${b.id}">Anulează</button></td></tr>`).join('');return dashboardShell(`<div class="dash-top"><div><h1>Programările</h1><p>Programările confirmate pentru ${esc(dash.shop.name)}.</p></div><a class="page-link" href="#cauta">↗ Vezi căutarea publică</a></div><section class="stat-grid"><article class="stat"><div class="stat-top">Programări viitoare</div><strong>${dash.bookings.length}</strong><small>Toate frizeriile și frizerii</small></article><article class="stat"><div class="stat-top">Servicii active</div><strong>${dash.services.filter(s=>s.active).length}</strong><small>Vizibile clienților</small></article><article class="stat"><div class="stat-top">Echipă</div><strong>${dash.team.filter(t=>t.active).length}</strong><small>Frizeri activi</small></article><article class="stat"><div class="stat-top">Abonament</div><strong style="font-size:20px">${dash.subscription.active?'Activ':'Inactiv'}</strong><small>${dash.subscription.active?'Până la '+fmtDate(dash.subscription.paid_until):'49 lei / lună'}</small></article></section><section class="panel"><div class="panel-head"><h2>Agenda</h2><a href="#dashboard-abonament">Gestionează abonamentul →</a></div><table class="appt-table"><thead><tr><th>DATA ȘI ORA</th><th>CLIENT</th><th>SERVICIU</th><th>FRIZER</th><th>ACȚIUNE</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Încă nu ai programări.</td></tr>'}</tbody></table></section>`,'dashboard')}
function servicePage(){let active=dash.services.filter(s=>s.active);return dashboardShell(`<div class="dash-top"><div><h1>Serviciile tale</h1><p>Definește serviciile, durata și prețurile afișate clienților.</p></div></div><section class="panel manage-panel"><form id="service-form" class="manage-form"><label class="field-label">Serviciu<input required class="input" name="name" placeholder="ex. Skin fade"></label><label class="field-label">Descriere<input class="input" name="description" placeholder="Detalii opționale"></label><label class="field-label">Durată (minute)<input class="input" name="duration" type="number" min="10" step="5" value="30" required></label><label class="field-label">Preț (lei)<input class="input" name="price" type="number" min="0" step="5" required></label><button class="btn">+ Adaugă serviciu</button></form><div class="manage-list">${active.map(s=>`<article class="manage-row"><div><strong>${esc(s.name)}</strong><small>${s.duration} min · ${s.price} lei · ${esc(s.description)}</small></div><button class="filter-btn" data-disable-service="${s.id}">Dezactivează</button></article>`).join('')||'<p>Adaugă primul serviciu ca să apari în căutare.</p>'}</div></section>`, 'dashboard-services')}
function teamPage(){let active=dash.team.filter(t=>t.active);return dashboardShell(`<div class="dash-top"><div><h1>Echipa ta</h1><p>Adaugă frizerii; configurează programul fiecăruia în secțiunea Programul echipei.</p></div></div><section class="panel manage-panel"><form id="staff-form" class="manage-form"><label class="field-label">Numele frizerului<input required class="input" name="name" placeholder="ex. Mihai Popescu"></label><label class="field-label">Rol<input class="input" name="role" placeholder="ex. Senior barber" value="Frizer"></label><button class="btn">+ Adaugă în echipă</button></form><div class="manage-list">${active.map(t=>`<article class="manage-row"><div><strong>${esc(t.name)}</strong><small>${esc(t.role)}</small></div><button class="filter-btn" data-disable-staff="${t.id}">Dezactivează</button></article>`).join('')}</div></section>`, 'dashboard-team')}
function hoursPage(){let active=dash.team.filter(t=>t.active);return dashboardShell(`<div class="dash-top"><div><h1>Programul echipei</h1><p>Setează orele de lucru individual; disponibilitatea se calculează după serviciu și programările existente.</p></div></div><div class="manage-list">${active.map(t=>{let sched={};try{sched=JSON.parse(t.weekly_schedule||'{}')}catch{}return `<form class="panel schedule-form" data-staff="${t.id}"><h2>${esc(t.name)}</h2>${weekdays.map((day,i)=>{let hrs=sched[String(i)]||[];return `<div class="schedule-edit-row"><label><input type="checkbox" name="open-${i}" ${hrs.length?'checked':''}> ${day}</label><input type="time" class="input" name="start-${i}" value="${hrs[0]||'09:00'}"><span>—</span><input type="time" class="input" name="end-${i}" value="${hrs[1]||'18:00'}"></div>`}).join('')}<button class="btn">Salvează programul</button></form>`}).join('')||'<div class="panel">Adaugă frizeri în echipă mai întâi.</div>'}</div>`, 'dashboard-hours')}
function subscriptionPage(){const plan=dash.subscription.plan||'free',active=dash.subscription.active;const options=plan==='free'?[['pro','PRO','49'],['business','BUSINESS','99']]:[];return dashboardShell(`<div class="dash-top"><div><h1>Planul frizeriei</h1><p>Alege funcțiile potrivite pentru etapa în care ești.</p></div></div><section class="panel manage-panel"><div class="subscription-card ${active?'is-active':'is-inactive'}"><span class="subscription-status">${active?'● ABONAMENT ACTIV':'● PLAN GRATUIT'}</span><div class="subscription-price">${plan.toUpperCase()} <small>${plan==='free'?'· 0 lei / lună':`· ${plan==='business'?99:49} lei / lună`}</small></div><p>${plan==='free'?'Dashboardul și configurarea sunt disponibile. Profilul nu apare în căutare, iar clienții nu pot face rezervări.':`Profilul public și rezervările sunt active${dash.subscription.paid_until?' până la '+fmtDate(dash.subscription.paid_until):''}.`}</p>${active?'<button class="btn" id="start-checkout">Gestionează abonamentul în Stripe</button>':''}<p class="manage-note">${active?'Gestionează reînnoirea sau anularea în portalul Stripe.':'Alege un plan plătit pentru a activa profilul public și rezervările.'}</p></div>${options.length?`<div class="plan-upgrade-grid">${options.map(([id,name,price])=>`<article class="plan-upgrade"><strong>${name}</strong><span>${price} lei / lună</span><button class="btn" data-subscription-plan="${id}">Activează ${name} →</button></article>`).join('')}</div>`:''}${plan==='business'?'<p class="manage-note">Funcțiile de fidelizare, AI și automatizări avansate sunt în dezvoltare.</p>':''}</section>`, 'dashboard-abonament')}
function notificationsPage(){let n=dash.notifications||{};return dashboardShell(`<div class="dash-top"><div><h1>Notificări</h1><p>Frizeria primește notificări la rezervare; clienții primesc reminder înainte de programare dacă e-mailul sau SMS-ul este configurat.</p></div></div><section class="panel manage-panel"><form id="notification-form"><label class="notification-option"><input type="checkbox" name="email" ${n.notification_email===0?'':'checked'}> E-mail către frizerie și confirmare către client <small>Necesită setările SMTP în server.</small></label><label class="notification-option"><input type="checkbox" name="sms" ${n.notification_sms?'checked':''}> SMS către frizerie și client <small>Necesită un cont Twilio configurat.</small></label><button class="btn" style="margin-top:18px">Salvează preferințele</button></form></section>`, 'dashboard-notificari')}
async function dashboardPage(route){let result=await api('/api/manage/dashboard');dash=result;switch(route){case'dashboard-services':return servicePage();case'dashboard-team':return teamPage();case'dashboard-hours':return hoursPage();case'dashboard-abonament':return subscriptionPage();case'dashboard-notificari':return notificationsPage();case'dashboard-profile':return shopProfilePage();default:return appointmentPage()}}
async function render(){let route=decodeURIComponent(location.hash.slice(1)||'');try{if(route===''){app.innerHTML=home();return}if(route==='confidentialitate'){app.innerHTML=privacyPage();return}if(route==='cauta'){app.innerHTML=await searchPage();return}if(route==='connect'||route==='login'){app.innerHTML=authPage(route);return}if(route.startsWith('frizerie/')){app.innerHTML=await profilePage(route.slice('frizerie/'.length));await refreshSlots();return}if(route==='confirmare'){app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><div class="success-icon">✓</div><h1>Programare confirmată</h1><p>Programarea la ${esc(publicShop?.name||'frizerie')} a fost înregistrată. Pentru detalii, sună la <a href="tel:${esc(publicShop?.phone||'')}">${esc(publicShop?.phone||'contactează frizeria')}</a>.</p><a class="btn full" href="#cauta">Caută alt frizer</a></section></main>`;return}if(route==='logout'){await api('/api/auth/logout',{method:'POST',body:'{}'});me=null;location.hash='';return}if(route.startsWith('dashboard')){let res=await api('/api/me');if(!res.user){location.hash='login';return}me=res;app.innerHTML=await dashboardPage(route);return}app.innerHTML=home()}catch(e){if(route.startsWith('frizerie/'))app.innerHTML=`${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="success-wrap"><section class="success-card"><div class="success-icon">✂</div><h1>Profil indisponibil</h1><p>${esc(e.message)}</p><a class="btn full" href="#cauta">Caută frizerii disponibile</a></section></main>`;else if(route.startsWith('dashboard')&&e.message.includes('Conectează-te'))location.hash='login';else{app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><h1>Nu s-a putut încărca pagina.</h1><p>${esc(e.message)}</p><a class="btn" href="#">Înapoi la început</a></section></main>`}}}
function defaultSchedule(){return Object.fromEntries([0,1,2,3,4,5].map(i=>[String(i),['09:00','19:00']]))}
function parseForm(form){return Object.fromEntries(new FormData(form).entries())}
app.addEventListener('click',async e=>{const slot=e.target.closest('[data-slot]');if(slot){publicSelection.time=slot.dataset.slot;document.querySelectorAll('[data-slot]').forEach(x=>x.classList.toggle('selected',x===slot));const s=publicShop.services.find(x=>String(x.id)===publicSelection.service);document.querySelector('#booking-summary').innerHTML=`<span>${esc(s.name)} · ${publicSelection.time}</span><strong>${s.price} lei</strong>`;document.querySelector('#booking-form button').disabled=false;return}const svc=e.target.closest('[data-select-service]');if(svc){publicSelection.service=svc.dataset.selectService;publicSelection.time='';app.innerHTML=await profilePage(publicShop.slug);await refreshSlots();return}const staff=e.target.closest('[data-select-staff]');if(staff){publicSelection.staff=staff.dataset.selectStaff;publicSelection.time='';app.innerHTML=await profilePage(publicShop.slug);await refreshSlots();return}const disableSvc=e.target.closest('[data-disable-service]');if(disableSvc){dash.services=dash.services.map(s=>s.id===Number(disableSvc.dataset.disableService)?{...s,active:0}:s);await api('/api/manage/services',{method:'PUT',body:JSON.stringify({services:dash.services})});dash=await api('/api/manage/dashboard');app.innerHTML=servicePage();return}const disableStaff=e.target.closest('[data-disable-staff]');if(disableStaff){dash.team=dash.team.map(t=>t.id===Number(disableStaff.dataset.disableStaff)?{...t,active:0}:t);await api('/api/manage/team',{method:'PUT',body:JSON.stringify({team:dash.team})});dash=await api('/api/manage/dashboard');app.innerHTML=teamPage();return}const cancel=e.target.closest('[data-cancel]');if(cancel){try{await api('/api/manage/bookings/cancel',{method:'POST',body:JSON.stringify({id:cancel.dataset.cancel})});toast('Programarea a fost anulată.');app.innerHTML=await dashboardPage('dashboard')}catch(err){toast(err.message)}return}if(e.target.closest('#start-checkout')){try{let r=await api('/api/billing/checkout',{method:'POST',body:'{}'});location.href=r.url}catch(err){toast(err.message)}}});
app.addEventListener('change',async e=>{if(e.target.matches('#booking-date,[data-select-service],[data-select-staff]')){if(e.target.id==='booking-date')publicSelection.date=e.target.value;publicSelection.time='';await refreshSlots()} });
async function refreshSlots(){if(!publicShop||!publicSelection.service||!publicSelection.staff||!publicSelection.date)return;const q=new URLSearchParams({date:publicSelection.date,service:publicSelection.service,staff:publicSelection.staff});try{let d=await api(`/api/public/shops/${encodeURIComponent(publicShop.slug)}/availability?${q}`),box=document.querySelector('#available-slots');if(!box)return;box.innerHTML=d.slots.length?d.slots.map(x=>`<button type="button" class="slot ${publicSelection.time===x?'selected':''}" data-slot="${x}">${x}</button>`).join(''):'<span class="manage-note">Nu sunt locuri libere în această zi.</span>'}catch(e){toast(e.message)}}
app.addEventListener('submit',async e=>{e.preventDefault();let data=parseForm(e.target);try{if(e.target.id==='auth-form'){let register=location.hash==='#connect';await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(data)});toast(register?'Contul frizeriei a fost creat.':'Te-ai conectat.');location.hash=register?'dashboard-abonament':'dashboard'}else if(e.target.id==='booking-form'){if(!publicSelection.time)throw new Error('Alege un interval disponibil.');await api('/api/public/bookings',{method:'POST',body:JSON.stringify({...data,slug:publicShop.slug,service_id:publicSelection.service,staff_id:publicSelection.staff,date:publicSelection.date,time:publicSelection.time})});location.hash='confirmare'}else if(e.target.id==='service-form'){dash.services.push({...data,duration:Number(data.duration),price:Number(data.price),active:1});await api('/api/manage/services',{method:'PUT',body:JSON.stringify({services:dash.services})});dash=await api('/api/manage/dashboard');app.innerHTML=servicePage();toast('Serviciul a fost salvat.')}else if(e.target.id==='staff-form'){dash.team.push({name:data.name,role:data.role,active:1,weekly_schedule:JSON.stringify(defaultSchedule())});await api('/api/manage/team',{method:'PUT',body:JSON.stringify({team:dash.team})});dash=await api('/api/manage/dashboard');app.innerHTML=teamPage();toast('Frizerul a fost adăugat.')}else if(e.target.matches('.schedule-form')){const sched={};for(let i=0;i<7;i++)if(data[`open-${i}`])sched[String(i)]=[data[`start-${i}`],data[`end-${i}`]];dash.team=dash.team.map(t=>t.id===Number(e.target.dataset.staff)?{...t,weekly_schedule:JSON.stringify(sched)}:t);await api('/api/manage/team',{method:'PUT',body:JSON.stringify({team:dash.team})});dash=await api('/api/manage/dashboard');app.innerHTML=hoursPage();toast('Programul echipei a fost salvat.')}else if(e.target.id==='notification-form'){await api('/api/manage/notifications',{method:'PUT',body:JSON.stringify({email:e.target.elements.email.checked,sms:e.target.elements.sms.checked})});toast('Preferințele au fost salvate.')}}catch(err){toast(err.message)}});

function galleryMarkup(shop){let photos=shop.photos||[];return photos.length?`<section id="galerie" class="shop-gallery" aria-label="Fotografii ${esc(shop.name)}">${photos.map(src=>`<img src="${esc(src)}" alt="Fotografie ${esc(shop.name)}" loading="lazy">`).join('')}</section>`:`<section id="galerie" class="profile-empty-gallery"><span>✂</span><p>Frizeria pregătește fotografiile de prezentare.</p></section>`}
function shopProfilePage(){let photos=dash.shop.photos||[],bookingLink=location.origin+'/#frizerie/'+encodeURIComponent(dash.shop.slug);setTimeout(renderShopQr,0);return dashboardShell(`<div class="dash-top"><div><h1>Profilul public</h1><p>Adaugă fotografii și o descriere, ca oamenii să-ți cunoască frizeria înainte să rezerve.</p></div><a class="page-link" href="#frizerie/${encodeURIComponent(dash.shop.slug)}">↗ Vezi profilul public</a></div><section class="panel manage-panel"><form id="shop-details-form" class="manage-form"><label class="field-label">Descrierea frizeriei<input class="input" name="tagline" maxlength="140" value="${esc(dash.shop.tagline||'')}" placeholder="ex. Tunsori moderne, atmosferă relaxată"></label><button class="btn">Salvează descrierea</button></form></section><section class="panel manage-panel qr-panel"><div class="panel-head"><h2>Cod QR pentru programări</h2><span>Link unic</span></div><p class="manage-note">Clienții scanează codul și ajung direct la profilul frizeriei, unde pot alege serviciul și ora.</p><div class="booking-qr-layout"><div id="shop-booking-qr" class="booking-qr" data-qr-url="${esc(bookingLink)}" aria-label="Cod QR pentru programări"></div><div class="booking-qr-actions"><label class="field-label">Link de programare<input class="input" id="public-shop-link" readonly value="${esc(bookingLink)}"></label><div class="hero-actions"><button class="btn" type="button" data-copy-link>Copiază linkul</button><button class="btn ghost" type="button" data-download-shop-qr>Descarcă QR</button></div>${dash.subscription.active?'<p class="manage-note">Profilul acceptă programări cât timp abonamentul este activ.</p>':'<p class="manage-note">Codul este pregătit. Profilul va accepta programări după activarea planului PRO sau BUSINESS.</p>'}</div></div></section><section class="panel manage-panel" style="margin-top:16px"><div class="panel-head"><h2>Fotografii</h2><span>${photos.length}/8</span></div><p class="manage-note">Încarcă până la 8 fotografii JPG, PNG sau WebP. Imaginile sunt redimensionate și salvate în contul tău.</p><form id="photo-form" class="manage-form"><label class="field-label">Alege fotografii<input class="input" type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple ${photos.length>=8?'disabled':''}></label><button class="btn" ${photos.length>=8?'disabled':''}>Încarcă fotografiile</button></form><div class="photo-manager">${photos.map((src,i)=>`<article><img src="${esc(src)}" alt="Fotografie ${i+1}" loading="lazy"><button type="button" class="filter-btn" data-remove-photo="${i}">Șterge</button></article>`).join('')||'<p>Nu ai încă fotografii în profil.</p>'}</div></section>`,'dashboard-profile')}
function renderShopQr(){const box=document.querySelector('#shop-booking-qr');if(!box)return;const link=box.dataset.qrUrl;box.innerHTML='';if(typeof QRCode==='undefined'){box.innerHTML='<p class="manage-note">Codul QR nu s-a încărcat. Reîncarcă pagina pentru a încerca din nou.</p>';return}new QRCode(box,{text:link,width:240,height:240,colorDark:'#171914',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H})}async function imageData(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));if(!blob)throw new Error('Fotografia nu a putut fi pregătită.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Fotografia nu a putut fi citită.'));reader.readAsDataURL(blob)})}
app.addEventListener('click',async e=>{const remove=e.target.closest('[data-remove-photo]');if(!remove)return;try{const photos=(dash.shop.photos||[]).filter((_,i)=>i!==Number(remove.dataset.removePhoto));await api('/api/manage/shop',{method:'PUT',body:JSON.stringify({photos})});dash=await api('/api/manage/dashboard');app.innerHTML=shopProfilePage();toast('Fotografia a fost eliminată.')}catch(err){toast(err.message)}});
app.addEventListener('submit',async e=>{if(e.target.id==='photo-form'){e.preventDefault();const files=Array.from(e.target.elements.photos.files||[]),available=8-(dash.shop.photos||[]).length;if(!files.length){toast('Alege cel puțin o fotografie.');return}if(files.length>available){toast(`Mai poți adăuga ${available} fotografii.`);return}try{for(const file of files){const data=await imageData(file);await api('/api/manage/photos',{method:'POST',body:JSON.stringify({data})})}dash=await api('/api/manage/dashboard');app.innerHTML=shopProfilePage();toast('Fotografiile au fost adăugate în profil.')}catch(err){toast(err.message)}return}if(e.target.id==='shop-details-form'){e.preventDefault();try{await api('/api/manage/shop',{method:'PUT',body:JSON.stringify({tagline:e.target.elements.tagline.value})});dash=await api('/api/manage/dashboard');app.innerHTML=shopProfilePage();toast('Descrierea a fost salvată.')}catch(err){toast(err.message)}}});

// Structura principală a platformei, separată între clienți și frizerii.
function shellHeader(right=''){return `<header class="subnav"><div class="wrap nav">${brand()}<nav class="navlinks"><a href="#cauta">Găsește barber</a><a href="#barberi">Pentru barberi</a><a href="#preturi">Prețuri</a></nav><div class="navright">${right||'<a class="login" href="#login">Intră în cont</a><a class="btn" href="#connect">Înscrie frizeria ↗</a>'}</div></div></header>`}
function siteFooter(){return `<footer class="footer"><div class="wrap"><span>© 2026 TunsPro</span><a href="#despre">Despre</a><a href="#preturi">Prețuri</a><a href="#confidentialitate">Confidențialitate</a><a href="mailto:tunsprogramari@gmail.com">Contact</a></div></footer>`}
function home(){return `${shellHeader('<a class="login" href="#login">Intră în cont</a><a class="btn" href="#connect">Pentru frizerii ↗</a>')}<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Găsește-ți următorul barber</div><h1>Un tuns bun<br>începe cu o<br><span>programare simplă.</span></h1><p class="hero-copy">Descoperă frizerii active, compară serviciile și rezervă online fără să suni.</p><div class="hero-actions"><a class="btn lime" href="#cauta">Găsește barber <span>↗</span></a><a class="btn ghost" href="#barberi">Ai o frizerie?</a></div><div class="socialproof"><span>Serviciu · frizer · zi · oră</span></div></div><div class="hero-visual"><span class="visual-tag">✦ Rezervare în câteva secunde</span><div class="barber-art">💈</div><div class="booking-card"><div class="booking-top"><div><strong>Alege ce ți se potrivește.</strong><br>Frizerii cu programări active</div><span>✂</span></div><div class="mini-slots"><span>Serviciu</span><span class="active">Barber</span><span>Dată</span><span>Oră</span></div></div></div></div></section><section class="section" id="cum-functioneaza"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Pentru clienți</div><h2>Găsești. Alegi.<br>Te-ai programat.</h2></div><p class="section-sub">Alege o frizerie, verifică serviciile și orele libere, apoi confirmă cu numele și telefonul tău.</p></div><div class="steps"><article class="step"><span class="step-icon">⌕</span><span class="step-num">01 / DESCOPERĂ</span><h3>Găsește un barber</h3><p>Caută după nume, oraș sau serviciu și folosește filtrele pentru rezultate potrivite.</p></article><article class="step"><span class="step-icon">◷</span><span class="step-num">02 / ALEGE</span><h3>Serviciu și disponibilitate</h3><p>Compară prețurile și alege frizerul, ziua și ora care îți convin.</p></article><article class="step"><span class="step-icon">✓</span><span class="step-num">03 / REZERVĂ</span><h3>Confirmare rapidă</h3><p>Rezervarea ajunge în agenda frizeriei; primești detaliile pe ecran.</p></article></div></div></section>${siteFooter()}`}
function directoryCard(s){const mapUrl='https://www.openstreetmap.org/search?query='+encodeURIComponent(`${s.address}, ${s.city}`);return `<article class="directory-card"><div class="directory-cover">${s.photos?.[0]?`<img src="${esc(s.photos[0])}" alt="${esc(s.name)}" loading="lazy">`:'<span>✂</span>'}<span class="pill">PROGRAMĂRI ACTIVE</span></div><div class="directory-content"><div class="directory-person"><span class="barber-face">💈</span><div><h2>${esc(s.name)}</h2><small>${esc(s.tagline||'Frizerie')}</small></div></div><h3>${esc(s.city)}</h3><p>📍 ${esc(s.address)}</p><div class="directory-tags">${s.services.slice(0,3).map(x=>`<span>${esc(x.name)} · ${x.price} lei</span>`).join('')}</div><div class="directory-card-actions"><a class="btn full" href="#frizerie/${encodeURIComponent(s.slug)}">Vezi profilul și rezervă</a><a class="map-link" href="${mapUrl}" target="_blank" rel="noopener">↗ Hartă și indicații</a></div></div></article>`}
function foldSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('ro')}
function renderDirectoryResults(){const box=document.querySelector('#search-results');if(!box)return;const term=foldSearch(document.querySelector('#shop-search')?.value).trim(),city=document.querySelector('#filter-city')?.value||'',service=document.querySelector('#filter-service')?.value||'',sort=document.querySelector('#sort-results')?.value||'name';let rows=(window.tunsproDirectoryCache||[]).filter(s=>{const text=foldSearch([s.name,s.city,s.address,s.tagline,...s.team.map(t=>t.name),...s.services.map(x=>x.name)].join(' '));return(!term||text.includes(term))&&(!city||s.city===city)&&(!service||s.services.some(x=>x.name===service))});if(sort==='price')rows.sort((a,b)=>(Math.min(...a.services.map(s=>s.price),Infinity)-Math.min(...b.services.map(s=>s.price),Infinity)));else rows.sort((a,b)=>a.name.localeCompare(b.name,'ro'));box.innerHTML=rows.map(directoryCard).join('');const count=document.querySelector('#result-count');if(count)count.textContent=`${rows.length} ${rows.length===1?'frizerie găsită':'frizerii găsite'}`;const empty=document.querySelector('.empty-results');if(empty)empty.classList.toggle('hidden',!!rows.length);}
async function searchPage(query=''){const d=await api('/api/public/shops');window.tunsproDirectoryCache=d.shops;const cities=[...new Set(d.shops.map(s=>s.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ro')),services=[...new Set(d.shops.flatMap(s=>s.services.map(x=>x.name)))].sort((a,b)=>a.localeCompare(b,'ro'));return `${shellHeader()}<main class="wrap directory-main"><div class="eyebrow">Descoperă frizerii cu programări active</div><h1>Găsește-ți următorul<br><span>barber.</span></h1><p class="directory-lead">Caută după nume, oraș, frizer sau serviciu. Deschide profilul pentru program și rezervări.</p><div class="directory-search"><span>⌕</span><input id="shop-search" type="search" value="${esc(query)}" placeholder="ex. fade, Andrei, București" autocomplete="off"><kbd>/</kbd></div><div class="directory-filters"><label>Oraș<select class="input" id="filter-city"><option value="">Toate orașele</option>${cities.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label>Serviciu<select class="input" id="filter-service"><option value="">Toate serviciile</option>${services.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label><label>Ordonează<select class="input" id="sort-results"><option value="name">Nume</option><option value="price">Preț minim</option></select></label></div><div class="directory-results"><strong id="result-count">${d.shops.length} ${d.shops.length===1?'frizerie găsită':'frizerii găsite'}</strong><span>Abonament activ · rezultate actualizate</span></div><div id="search-results" class="directory-grid">${d.shops.map(directoryCard).join('')}</div><div class="empty-results ${d.shops.length?'hidden':''}"><span>⌕</span><h2>Nu am găsit frizerii disponibile.</h2><p>În acest moment apar aici doar frizeriile cu abonament activ.</p><p>Ai o frizerie? <a href="#connect"><strong>Creează primul profil</strong></a></p></div></main>${siteFooter()}`}
async function profilePage(slug){const {shop}=await api('/api/public/shops/'+encodeURIComponent(slug));publicShop=shop;if(!publicSelection.service&&shop.services[0])publicSelection.service=String(shop.services[0].id);if(!publicSelection.staff&&shop.team[0])publicSelection.staff=String(shop.team[0].id);if(!publicSelection.date){const d=new Date();d.setDate(d.getDate()+1);publicSelection.date=d.toISOString().slice(0,10)}const mapUrl='https://www.openstreetmap.org/search?query='+encodeURIComponent(`${shop.address}, ${shop.city}`);return `${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="wrap profile-page"><section class="salon-hero"><div class="salon-identity"><span class="pill">PROGRAMĂRI ONLINE ACTIVE</span><h1>${esc(shop.name)}</h1><div class="salon-meta"><span>📍 ${esc(shop.address)}, ${esc(shop.city)}</span><span>✦ ${esc(shop.tagline||'Frizerie')}</span></div><a class="profile-map-link" href="${mapUrl}" target="_blank" rel="noopener">Deschide locația pe hartă ↗</a></div></section><nav class="profile-tabs"><button type="button" data-profile-scroll="galerie">Galerie</button><button type="button" data-profile-scroll="servicii">Servicii și prețuri</button><button type="button" data-profile-scroll="disponibilitate">Disponibilitate</button><button type="button" data-profile-scroll="recenzii">Recenzii</button></nav>${galleryMarkup(shop)||'<section class="profile-empty-gallery"><span>✂</span><p>Frizeria pregătește fotografiile de prezentare.</p></section>'}<div class="salon-grid"><section class="salon-main"><section id="servicii"><h2>Servicii și prețuri</h2><div class="service-list">${shop.services.map(s=>`<button class="service ${String(s.id)===publicSelection.service?'selected':''}" data-select-service="${s.id}"><span><strong>${esc(s.name)}</strong><small>${s.duration} min · ${esc(s.description||'')}</small></span><span class="service-price">${s.price} lei</span></button>`).join('')||'<p>Servicii indisponibile momentan.</p>'}</div></section><section id="echipa" class="profile-section"><h2>Alege barberul</h2><div class="barbers">${shop.team.map(t=>`<button class="barber ${String(t.id)===publicSelection.staff?'selected':''}" data-select-staff="${t.id}"><span class="barber-face">✂</span><span><strong>${esc(t.name)}</strong><small>${esc(t.role)}</small></span></button>`).join('')}</div></section><section id="disponibilitate" class="profile-section"><h2>Alege data</h2><input class="input profile-date" id="booking-date" type="date" value="${esc(publicSelection.date)}" min="${new Date().toISOString().slice(0,10)}"></section><section id="recenzii" class="profile-section reviews-coming"><h2>Recenzii</h2><p>Recenziile verificate vor fi disponibile după activarea conturilor de client și a evaluărilor pentru programări încheiate.</p></section></section><aside class="book-card"><h3>Rezervă o oră</h3><p>${esc(shop.name)} · ${esc(shop.city)}</p><div id="available-slots" class="slots"><span class="manage-note">Alege serviciul, barberul și data.</span></div><form id="booking-form"><label class="field-label">Numele tău<input required class="input" name="client" autocomplete="name"></label><label class="field-label">Telefon<input required class="input" name="phone" type="tel" autocomplete="tel"></label><label class="field-label">E-mail (opțional)<input class="input" name="email" type="email" autocomplete="email"></label><p class="privacy-inline">Datele sunt folosite pentru gestionarea programării. <a href="#confidentialitate" target="_blank">Politica de confidențialitate</a> · păstrare: 12 luni, apoi anonimizare.</p><button class="btn full" style="margin-top:15px" ${publicSelection.time?'':'disabled'}>Confirmă programarea</button></form><div id="booking-summary" class="booking-summary"><span>Selectează o oră</span></div></aside></div></main>${siteFooter()}`}
function dashboardShell(content,active){const groups=[['AGENDA',[['dashboard','Calendar','▦'],['dashboard-clients','Clienți','♙']]],['GESTIUNE',[['dashboard-services','Servicii','✂'],['dashboard-team','Echipă','♧'],['dashboard-hours','Program echipă','◷'],['dashboard-profile','Profil public','▣']]],['CONT',[['dashboard-abonament','Abonament','▤'],['dashboard-notificari','Notificări','✉']]]];return `<div class="dashboard"><div class="dash-layout"><aside class="sidebar">${brand()}${groups.map(([title,items])=>`<div class="side-label">${title}</div><nav>${items.map(([route,label,ico])=>`<a class="side-link ${active===route?'active':''}" href="#${route}"><span class="ico">${ico}</span><span class="label">${label}</span></a>`).join('')}</nav>`).join('')}<a class="side-link" href="#logout"><span class="ico">↪</span><span class="label">Ieșire din cont</span></a><div class="side-bottom"><strong>${esc(dash?.shop?.name||'Frizeria')}</strong><div style="color:var(--muted);margin-top:5px">${esc(dash?.shop?.city||'')}</div></div></aside><main class="dash-main">${content}</main></div></div>`}
function clientsPage(){const map=new Map();for(const b of dash.bookings){if(!b.phone||b.client==='Date anonimizate')continue;const key=b.phone.replace(/\D/g,'');if(!map.has(key))map.set(key,{name:b.client,phone:b.phone,email:b.email||'',visits:0,last:b.starts});const item=map.get(key);item.visits++;if(b.starts>item.last)item.last=b.starts}const rows=[...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'ro'));return dashboardShell(`<div class="dash-top"><div><h1>Clienți</h1><p>Clienții care au rezervat la ${esc(dash.shop.name)}.</p></div></div><section class="panel"><div class="panel-head"><h2>${rows.length} ${rows.length===1?'client':'clienți'}</h2><span class="manage-note">Datele anonimizate nu sunt afișate</span></div><div class="client-directory">${rows.map(c=>`<article class="client-record"><div class="client-avatar">${esc(c.name.slice(0,1).toUpperCase())}</div><div><strong>${esc(c.name)}</strong><small>${esc(c.phone)}${c.email?' · '+esc(c.email):''}</small></div><span class="client-visits">${c.visits} ${c.visits===1?'programare':'programări'}</span></article>`).join('')||'<p class="manage-note">Lista se completează pe măsură ce primești rezervări.</p>'}</div></section>`,'dashboard-clients')}
function aboutPage(){return `${shellHeader()}<main class="wrap info-page"><div class="eyebrow">Despre TunsPro</div><h1>Mai simplu pentru clienți.<br><span>Mai organizat pentru frizerii.</span></h1><p class="directory-lead">TunsPro conectează clienții cu frizerii care acceptă programări online și oferă frizeriilor o agendă simplu de gestionat.</p><div class="steps"><article class="step"><h3>Pentru clienți</h3><p>Cauți frizerii active, compari servicii și prețuri, apoi rezervi fără cont.</p><a href="#cauta">Găsește un barber ↗</a></article><article class="step"><h3>Pentru frizerii</h3><p>Configurezi echipa, serviciile, programul și profilul public din dashboard.</p><a href="#barberi">Cum te conectezi ↗</a></article></div></main>${siteFooter()}`}
function pricesPage(){const plans=[{id:'free',name:'FREE',price:'0',desc:'Pentru frizerii mici care vor să-și pregătească profilul.',features:['Dashboard și configurare internă','Servicii, program și profil pregătite','Un singur barber','Fără listare publică sau rezervări'],cta:'Creează cont gratuit'},{id:'pro',name:'PRO',price:'49',desc:'Tot ce ai nevoie ca să primești și să gestionezi programări.',features:['Profil public în căutare','Programări nelimitate și calendar','Notificări și recenzii','Clienți și statistici','Un singur barber'],cta:'Începe cu PRO',featured:true},{id:'business',name:'BUSINESS',price:'99',desc:'Pentru frizerii cu echipă și promovare în creștere.',features:['Tot ce include PRO','Mai mulți barberi','Marketing și statistici avansate','Fidelizare și automatizări — în dezvoltare'],cta:'Alege BUSINESS'}];return `${shellHeader()}<main class="wrap info-page pricing-page"><div class="eyebrow">Planuri pentru fiecare frizerie</div><h1>Începe simplu.<br><span>Crește în ritmul tău.</span></h1><p class="directory-lead">FREE te ajută să configurezi. PRO și BUSINESS activează profilul public și rezervările online.</p><section class="pricing-grid">${plans.map(p=>`<article class="panel plan-card ${p.featured?'plan-featured':''}"><span class="pill">${p.name}${p.featured?' · RECOMANDAT':''}</span><div class="subscription-price">${p.price} <small>lei / lună</small></div><p>${p.desc}</p><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><a class="btn ${p.featured?'lime':''}" href="#connect">${p.cta} ↗</a></article>`).join('')}</section><p class="manage-note pricing-note">Abonamentele PRO și BUSINESS se activează din dashboard. Plățile recurente sunt procesate prin Stripe.</p><section class="panel ai-roadmap"><span class="pill">ETAPĂ VIITOARE · AI</span><h2>Rezervări și recomandări mai inteligente</h2><p>AI-ul este în planul de dezvoltare, după lansarea funcțiilor de bază.</p><div class="ai-roadmap-grid"><article><strong>01 · Programare asistată</strong><p>„Vreau un skin fade și barbă vineri după ora 18.”</p><small>AI-ul va căuta serviciile și disponibilitatea și va propune ore libere pentru confirmare.</small></article><article><strong>02 · AI Barber Advisor</strong><p>Clientul încarcă o fotografie și primește sugestii de tunsori.</p><small>Funcția va fi evaluată într-o etapă ulterioară.</small></article></div><p class="manage-note">Aceste funcții nu sunt disponibile în versiunea MVP.</p></section></main>${siteFooter()}`}
function barbersPage(){return `${shellHeader('<a class="btn" href="#connect">Creează contul frizeriei ↗</a>')}<main class="wrap info-page"><div class="eyebrow">TunsPro pentru frizerii</div><h1>Agenda ta,<br><span>într-un singur loc.</span></h1><p class="directory-lead">Configurezi profilul, serviciile, echipa și programul. Clienții se programează online când abonamentul este activ.</p><div class="steps"><article class="step"><span class="step-num">01 / CREEAZĂ</span><h3>Contul frizeriei</h3><p>Introduci datele frizeriei și alegi o adresă pentru profilul public.</p></article><article class="step"><span class="step-num">02 / CONFIGUREAZĂ</span><h3>Servicii și echipă</h3><p>Adaugi prețurile, durata fiecărui serviciu și programul barberilor.</p></article><article class="step"><span class="step-num">03 / PUBLICĂ</span><h3>Activează programările</h3><p>După activarea abonamentului, frizeria poate apărea în căutare.</p></article></div><div class="feature-inner" style="margin-top:35px"><a class="btn" href="#preturi">Vezi prețurile →</a><a class="btn ghost" href="#login">Intră în dashboard</a></div></main>${siteFooter()}`}
async function dashboardPage(route){dash=await api('/api/manage/dashboard');switch(route){case'dashboard-services':return servicePage();case'dashboard-team':return teamPage();case'dashboard-hours':return hoursPage();case'dashboard-abonament':return subscriptionPage();case'dashboard-notificari':return notificationsPage();case'dashboard-profile':return shopProfilePage();case'dashboard-clients':return clientsPage();default:return appointmentPage()}}
async function render(){const route=decodeURIComponent(location.hash.slice(1)||'');try{if(route===''){app.innerHTML=home();return}if(route==='cauta'){app.innerHTML=await searchPage();renderDirectoryResults();return}if(route==='preturi'){app.innerHTML=pricesPage();return}if(route==='despre'){app.innerHTML=aboutPage();return}if(route==='barberi'){app.innerHTML=barbersPage();return}if(route==='confidentialitate'){app.innerHTML=privacyPage();return}if(route==='connect'||route==='login'){app.innerHTML=authPage(route);return}if(route.startsWith('frizerie/')){app.innerHTML=await profilePage(route.slice('frizerie/'.length));await refreshSlots();return}if(route==='confirmare'){app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><div class="success-icon">✓</div><h1>Programare confirmată</h1><p>Programarea la ${esc(publicShop?.name||'frizerie')} a fost înregistrată. Pentru detalii, sună la <a href="tel:${esc(publicShop?.phone||'')}">${esc(publicShop?.phone||'contactează frizeria')}</a>.</p><a class="btn full" href="#cauta">Caută alt frizer</a></section></main>${siteFooter()}`;return}if(route==='logout'){await api('/api/auth/logout',{method:'POST',body:'{}'});me=null;location.hash='';return}if(route.startsWith('dashboard')){const res=await api('/api/me');if(!res.user){location.hash='login';return}me=res;app.innerHTML=await dashboardPage(route);return}app.innerHTML=home()}catch(e){if(route.startsWith('frizerie/'))app.innerHTML=`${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="success-wrap"><section class="success-card"><div class="success-icon">✂</div><h1>Profil indisponibil</h1><p>${esc(e.message)}</p><a class="btn full" href="#cauta">Caută frizerii disponibile</a></section></main>`;else if(route.startsWith('dashboard')&&e.message.includes('Conectează-te'))location.hash='login';else{app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><h1>Nu s-a putut încărca pagina.</h1><p>${esc(e.message)}</p><a class="btn" href="#">Înapoi la început</a></section></main>`}}}
app.addEventListener('input',e=>{if(e.target.id==='shop-search')renderDirectoryResults()});
app.addEventListener('change',e=>{if(['filter-city','filter-service','sort-results'].includes(e.target.id))renderDirectoryResults()});
function appointmentPage(){const upcoming=dash.bookings.filter(b=>new Date(b.starts)>=new Date()).sort((a,b)=>new Date(a.starts)-new Date(b.starts));const rows=upcoming.map(b=>`<tr><td><strong>${new Date(b.starts).toLocaleString('ro-RO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</strong></td><td class="client-cell">${esc(b.client)}<small>${esc(b.phone)} ${b.email?`· ${esc(b.email)}`:''}</small></td><td>${esc(b.service_name)}<small>${b.price} lei · ${b.duration} min</small></td><td>${esc(b.staff_name)}</td><td><button class="filter-btn" data-cancel="${b.id}">Anulează</button></td></tr>`).join('');return dashboardShell(`<div class="dash-top"><div><h1>Calendar</h1><p>Programările viitoare pentru ${esc(dash.shop.name)}.</p></div><a class="page-link" href="#cauta">↗ Vezi căutarea publică</a></div><section class="stat-grid"><article class="stat"><div class="stat-top">Programări viitoare</div><strong>${upcoming.length}</strong><small>Rezervări confirmate</small></article><article class="stat"><div class="stat-top">Servicii active</div><strong>${dash.services.filter(s=>s.active).length}</strong><small>Vizibile clienților</small></article><article class="stat"><div class="stat-top">Echipă</div><strong>${dash.team.filter(t=>t.active).length}</strong><small>Frizeri activi</small></article><article class="stat"><div class="stat-top">Abonament</div><strong style="font-size:20px">${dash.subscription.active?'Activ':'Inactiv'}</strong><small>${dash.subscription.active?'Până la '+fmtDate(dash.subscription.paid_until):'49 lei / lună'}</small></article></section><section class="panel"><div class="panel-head"><h2>Următoarele programări</h2><a href="#dashboard-clients">Vezi clienții →</a></div><table class="appt-table"><thead><tr><th>DATA ȘI ORA</th><th>CLIENT</th><th>SERVICIU</th><th>FRIZER</th><th>ACȚIUNE</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Nu ai programări viitoare.</td></tr>'}</tbody></table></section>`,'dashboard')}

app.addEventListener('click',e=>{const link=e.target.closest('[data-profile-scroll]');if(!link)return;document.getElementById(link.dataset.profileScroll)?.scrollIntoView({behavior:'smooth',block:'start'})});
